package com.bank.longest;

import java.util.*;
import java.util.logging.*;

public class LongestDemo {
    private static final Logger log = Logger.getLogger("Longest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> refs = List.of("SAV2001", "CUR3001", "ACC10", "TXN900001");
        LongestService service = new LongestService();

        log.info(() -> "Longest ref: " + service.longest(refs).orElse("none"));
        log.info(() -> "Empty      : " + service.longest(List.of()).orElse("none"));
    }
}

// ─── Would be in service/LongestService.java ───
class LongestService {
    Optional<String> longest(List<String> items) {
        return items.stream()
            .filter(Objects::nonNull)                                 // guard nulls
            .max(Comparator.comparingInt(String::length)             // by length (primitive)
                .thenComparing(Comparator.naturalOrder()));           // deterministic tie-break
    }
}
